/**
 * Generates the view configuration documentation using the view-config schema.
 * Reads from  : schemas/json/view-config.json
 * Publishes to: docs/reference-guides/view-config-reference.md
 *
 * The reference doc is hand-written prose with one autogenerated block per
 * top-level schema property (`default_view`, `default_layouts`, `view_list`,
 * and `form`), delimited by per-section token pairs:
 *
 *     <!-- START TOKEN Autogenerated - DO NOT EDIT (default_view) -->
 *     <!-- END TOKEN Autogenerated - DO NOT EDIT (default_view) -->
 */

/**
 * External dependencies
 */
import fs from 'node:fs/promises';
import $RefParser from '@apidevtools/json-schema-ref-parser';
import { fileURLToPath } from 'node:url';

/**
 * @typedef {import('@apidevtools/json-schema-ref-parser').JSONSchema} JSONSchema
 */

/**
 * Path to view-config json schema file.
 *
 * @type {string}
 */
const VIEW_CONFIG_SCHEMA_PATH = fileURLToPath(
	new URL( '../../schemas/json/view-config.json', import.meta.url )
);

/**
 * Path to docs file.
 *
 * @type {string}
 */
const REFERENCE_DOC_PATH = fileURLToPath(
	new URL(
		'../../docs/reference-guides/view-config-reference.md',
		import.meta.url
	)
);

/**
 * Returns the start/end tokens delimiting the autogenerated block of a
 * top-level schema property.
 *
 * @param {string} section Top-level schema property name.
 * @return {[string, string]} Start and end tokens.
 */
function getTokens( section ) {
	return [
		`<!-- START TOKEN Autogenerated - DO NOT EDIT (${ section }) -->`,
		`<!-- END TOKEN Autogenerated - DO NOT EDIT (${ section }) -->`,
	];
}

/**
 * Maximum number of object properties serialized inline as `{ a, b, c }`
 * in the Type column. Larger objects are serialized as `object`.
 *
 * @type {number}
 */
const MAX_INLINE_OBJECT_KEYS = 5;

/**
 * Maximum length of a type serialized inline in the Type column — an enum
 * as `"a" | "b" | "c"`, an object with its property types as
 * `{ a: string, b: boolean }`. Longer enums fall back to their base type
 * and longer objects to the key summary form (`{ a, b }`); their values or
 * types are expected to be covered by the property description or a
 * dedicated section.
 *
 * @type {number}
 */
const MAX_INLINE_LENGTH = 80;

/**
 * Whether a schema is a union of objects discriminated by a single-value
 * `type` enum (e.g. the form layout variants). Those unions are documented
 * with their own per-variant tables, so the Type column summarizes them
 * as a plain `object`.
 *
 * @param {JSONSchema} schema JSON schema.
 * @return {boolean} Whether the schema is a discriminated union.
 */
function isDiscriminatedUnion( schema ) {
	const branches = schema.oneOf || schema.anyOf;
	return (
		Array.isArray( branches ) &&
		branches.every(
			( branch ) => branch.properties?.type?.enum?.length === 1
		)
	);
}

/**
 * Serialize a schema type, without the wrapping backticks.
 *
 * @param {JSONSchema} schema JSON schema.
 * @return {string} Serialized type.
 */
function serializeType( schema ) {
	const branches = schema.oneOf || schema.anyOf;
	if ( branches ) {
		if ( isDiscriminatedUnion( schema ) ) {
			return 'object';
		}
		return [ ...new Set( branches.map( serializeType ) ) ].join( ' | ' );
	}
	if ( Array.isArray( schema.type ) ) {
		return schema.type.join( ' | ' );
	}
	if ( schema.enum?.length >= 1 ) {
		const values = schema.enum
			.map( ( value ) => `"${ value }"` )
			.join( ' | ' );
		if ( values.length <= MAX_INLINE_LENGTH ) {
			return values;
		}
	} else if ( schema.type === 'array' ) {
		return schema.items
			? `[ ${ serializeType( schema.items ) } ]`
			: 'array';
	} else if ( schema.type === 'object' ) {
		return serializeObject( schema );
	}
	return schema.type ?? 'any';
}

/**
 * Serialize an object schema. Small objects are serialized inline with
 * their property types (`{ field: string, direction: "asc" | "desc" }`),
 * falling back to a key summary (`{ field, direction }`) when the typed
 * form is too long, and to `object` when there are too many keys.
 *
 * @param {JSONSchema} schema Object JSON schema.
 * @return {string} Serialized object type.
 */
function serializeObject( schema ) {
	const properties = schema.properties ?? {};
	const keys = Object.keys( properties );
	if ( keys.length > 0 && keys.length <= MAX_INLINE_OBJECT_KEYS ) {
		const typed = `{ ${ keys
			.map(
				( key ) => `${ key }: ${ serializeType( properties[ key ] ) }`
			)
			.join( ', ' ) } }`;
		return typed.length <= MAX_INLINE_LENGTH
			? typed
			: `{ ${ keys.join( ', ' ) } }`;
	}
	if ( schema.additionalProperties?.properties ) {
		return `{ [ field ]: ${ serializeObject(
			schema.additionalProperties
		) } }`;
	}
	return 'object';
}

/**
 * Wrap a value as inline code for use inside a markdown table cell.
 *
 * A backtick code span does not protect pipes from being parsed as cell
 * delimiters. GitHub requires escaping them (`\|`) but other renderers
 * may not. A raw HTML code tag with pipes as HTML entities
 * renders correctly in both.
 *
 * @see https://github.com/WordPress/gutenberg/pull/81168#discussion_r3719197568
 *
 * @param {string} value Code content.
 * @return {string} Inline code markup.
 */
function codeCell( value ) {
	return value.includes( '|' )
		? `<code>${ value.replace( /\|/g, '&#124;' ) }</code>`
		: `\`${ value }\``;
}

/**
 * Escape a value for use inside a markdown table cell.
 *
 * @param {string} value Cell content.
 * @return {string} Escaped cell content.
 */
function escapeCell( value ) {
	return value.replace( /\|/g, '\\|' ).replace( /\n/g, ' ' );
}

/**
 * Generate a property table from a schema properties map. A Default column
 * is added when at least one property declares a default.
 *
 * @param {Record<string, JSONSchema>} properties    Schema properties map.
 * @param {Record<string, string>}     typeOverrides Per-property Type column
 *                                                   content, replacing the
 *                                                   serialized schema type.
 * @return {string} Markdown table.
 */
function generateTable( properties, typeOverrides = {} ) {
	const entries = Object.entries( properties );
	const hasDefaults = entries.some( ( [ , schema ] ) => 'default' in schema );

	let md = hasDefaults
		? '| Property | Description | Type | Default |\n| -------- | ----------- | ---- | ------- |\n'
		: '| Property | Description | Type |\n| -------- | ----------- | ---- |\n';
	for ( const [ property, schema ] of entries ) {
		const cells = [
			property,
			escapeCell( schema.description ?? '' ),
			escapeCell(
				codeCell( typeOverrides[ property ] ?? serializeType( schema ) )
			),
		];
		if ( hasDefaults ) {
			cells.push(
				'default' in schema
					? codeCell( JSON.stringify( schema.default ) )
					: ''
			);
		}
		md += `| ${ cells.join( ' | ' ) } |\n`;
	}
	return md;
}

/**
 * Generate the `default_view` block.
 *
 * @param {JSONSchema} schema Dereferenced view-config schema.
 * @return {string} Markdown content.
 */
function generateDefaultView( schema ) {
	// The `layout` keys are documented per layout type in the
	// `default_layouts` subsections, which the description links to.
	return generateTable( schema.properties.default_view.properties, {
		layout: 'object',
	} );
}

/**
 * Generate the `default_layouts` block: a summary table of the available
 * layout types, followed by one subsection per type with its `layout`
 * options.
 *
 * @param {JSONSchema} schema Dereferenced view-config schema.
 * @return {string} Markdown content.
 */
function generateDefaultLayouts( schema ) {
	const layouts = schema.properties.default_layouts.properties;

	let md = generateTable( layouts );
	for ( const [ type, subschema ] of Object.entries( layouts ) ) {
		md += `\n### ${ type }\n\n`;
		md += `${ subschema.description } In addition to the [view properties](#default_view), the \`layout\` key accepts:\n\n`;
		md += generateTable( subschema.properties.layout.properties );
	}
	return md;
}

/**
 * Generate the `view_list` block.
 *
 * @param {JSONSchema} schema Dereferenced view-config schema.
 * @return {string} Markdown content.
 */
function generateViewList( schema ) {
	return generateTable( schema.properties.view_list.items.properties );
}

/**
 * Generate the `form` block: the top-level form table, the form field object
 * table, and one subsection per form layout type.
 *
 * @param {JSONSchema} schema Dereferenced view-config schema.
 * @return {string} Markdown content.
 */
function generateForm( schema ) {
	const form = schema.properties.form;

	let md = generateTable( form.properties );

	// The object variant of a form field (the other variant is a plain id).
	const formFieldObject = form.properties.fields.items.oneOf.find(
		( branch ) => branch.properties
	);
	md += '\n### Form fields\n\n';
	md += 'An entry of `fields` declared as an object accepts:\n\n';
	md += generateTable( formFieldObject.properties );

	md += '\n### Form layout types\n\n';
	md +=
		'Both the form-level `layout` and a field-level `layout` accept one of the following objects, discriminated by their `type` property:\n\n';
	for ( const variant of form.properties.layout.oneOf ) {
		md += `#### ${ variant.properties.type.enum[ 0 ] }\n\n`;
		md += `${ variant.description }\n\n`;
		md += generateTable( variant.properties );
		md += '\n';
	}
	return md.replace( /\n$/, '' );
}

/**
 * Section generators, keyed by top-level schema property.
 *
 * @type {Record<string, (schema: JSONSchema) => string>}
 */
const SECTIONS = {
	default_view: generateDefaultView,
	default_layouts: generateDefaultLayouts,
	view_list: generateViewList,
	form: generateForm,
};

/**
 * Escape the special regex characters of a string literal.
 *
 * @param {string} value String literal.
 * @return {string} Escaped string.
 */
function escapeRegExp( value ) {
	return value.replace( /[.*+?^${}()|[\]\\]/g, '\\$&' );
}

/**
 * Main function.
 */
async function main() {
	const schema = await $RefParser.dereference( VIEW_CONFIG_SCHEMA_PATH, {
		parse: { binary: false, text: false, yaml: false },
		resolve: { external: false },
	} );

	let doc = await fs.readFile( REFERENCE_DOC_PATH, {
		encoding: 'utf8',
		flag: 'r',
	} );

	for ( const [ section, generate ] of Object.entries( SECTIONS ) ) {
		const [ startToken, endToken ] = getTokens( section );
		if ( ! doc.includes( startToken ) || ! doc.includes( endToken ) ) {
			throw new Error(
				`Missing "${ section }" tokens in ${ REFERENCE_DOC_PATH }.`
			);
		}
		doc = doc.replace(
			new RegExp(
				`${ escapeRegExp( startToken ) }.*${ escapeRegExp(
					endToken
				) }`,
				's'
			),
			() => `${ startToken }\n${ generate( schema ) }\n${ endToken }`
		);
	}

	await fs.writeFile( REFERENCE_DOC_PATH, doc, { encoding: 'utf8' } );
}

main().catch( ( error ) => {
	console.error( error );
	process.exit( 1 );
} );
